import{_ as r}from"./plugin-vue_export-helper-c27b6911.js";import{r as d,o,c as i,a as e,b as s,d as a,f as t}from"./app-98787eb3.js";const l={},c=t(`<h1 id="docker-的代理问题" tabindex="-1"><a class="header-anchor" href="#docker-的代理问题" aria-hidden="true">#</a> Docker 的代理问题</h1><h2 id="国内镜像加速" tabindex="-1"><a class="header-anchor" href="#国内镜像加速" aria-hidden="true">#</a> 国内镜像加速</h2><p>对于国内加速镜像，直接设置镜像地址就好了：编辑/etc/docker/daemon.json添加</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token punctuation">{</span>
    <span class="token string">&quot;registry-mirrors&quot;</span><span class="token builtin class-name">:</span> <span class="token punctuation">[</span><span class="token string">&quot;https://docker.mirrors.ustc.edu.cn&quot;</span><span class="token punctuation">]</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="docker-pull-拉取镜像时设置代理" tabindex="-1"><a class="header-anchor" href="#docker-pull-拉取镜像时设置代理" aria-hidden="true">#</a> docker pull 拉取镜像时设置代理</h2><p>首先， docker pull 和 docker build/docker run 使用代理的方式不一样！</p><p>docker pull 的代理被 systemd 接管，所以需要设置 systemd…</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">sudo</span> <span class="token function">vim</span> /etc/systemd/system/docker.service.d/http-proxy.conf
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>Environment=&quot;HTTP_PROXY=http://127.0.0.1:7890&quot;
Environment=&quot;HTTPS_PROXY=http://127.0.0.1:7890&quot;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>[Service] 这里的127.0.0.1是直接用了本机的 http 代理，然后重启服务才能生效</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">sudo</span> systemctl daemon-reload
<span class="token function">sudo</span> systemctl restart <span class="token function">docker</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>可以通过</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">sudo</span> systemctl show <span class="token parameter variable">--property</span><span class="token operator">=</span>Environment <span class="token function">docker</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>看到设置的环境变量。然后docker pull就会使用代理啦！</p><h2 id="build-镜像时使用代理" tabindex="-1"><a class="header-anchor" href="#build-镜像时使用代理" aria-hidden="true">#</a> build 镜像时使用代理</h2><p>在 build 时添加 --build-arg 参数来设置生成镜像时使用的环境变量</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>docker build --build-arg http_proxy=http://172.17.0.1:8123 --build-arg https_proxy=http://172.17.0.1:8123 -t image_name .
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>这里需要注意的是 <code>ip</code> 地址用了默认虚拟网卡<code>docker0</code>的地址<code>172.17.0.1</code>，因为build的时候network参数默认为bridge，即docker内部会使用这个网段，因为要访问到宿主机的代理只能这样访问； 另外，也可以设置参数--network=host 来直接和宿主机共用网络，就能直接使用127.0.0.1来访问到宿主机了</p><h2 id="设置-docker-全局代理" tabindex="-1"><a class="header-anchor" href="#设置-docker-全局代理" aria-hidden="true">#</a> 设置 docker 全局代理</h2>`,19),p={href:"https://docs.docker.com/network/proxy/",target:"_blank",rel:"noopener noreferrer"},u=t(`<p>注意新版和旧版本(17.07以前)设置方法不一样，比旧版更简单而且不需要重启服务,网上文章基本都是针对旧版本的,可能未来又变化了,所以多看官方文档~ 以及这种设置方法只对 build 和 run 的容易有用， docker pull 要按照上面的方法设置。</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">vim</span> ~/.docker/config.json
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>{
 &quot;proxies&quot;:
 {
   &quot;default&quot;:
   {
     &quot;httpProxy&quot;: &quot;http://172.17.0.1:8123&quot;,
     &quot;httpsProxy&quot;: &quot;http://172.17.0.1:8123&quot;,
     &quot;noProxy&quot;: &quot;localhost,127.0.0.1,.daocloud.io&quot;
   }
 }
}
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这样设置后，build和run都会将http_proxy和https_proxy ftp_proxy变量设置成对应的代理地址，如果你在容器里面不想使用这个代理了，需要export http_proxy= 和 export https_proxy= 将两个变量设置为空</p><p>注意:</p>`,5),h=e("code",null,"http",-1),v=e("code",null,"https",-1),b=e("code",null,"ftp",-1),m={href:"https://neucrack.com/p/275",target:"_blank",rel:"noopener noreferrer"},k=e("li",null,[e("p",null,"这里使用了172.17.0.1(docker 虚拟网卡地址), 而不是127.0.0.1, 这是因为这是从容器内部的角度来看的, 容器内部要使用代理,默认情况下只能访问这个虚拟网卡的地址, 127.0.0.1是容器内部, 如果代理在宿主机, 要使用 虚拟网卡的地址才能访问到.")],-1),g=e("li",null,[e("p",null,"这个文件一旦存在, docker就会使用这里面的代理, 包括创建的容器都会使用它。 所以不需要代理了, 需要关闭代理, 就是把文件重命名一下就好了, 这点用起来确实挺麻烦，也许未来会优化体验吧。")],-1),x=e("li",null,[e("p",null,"注意， 一个容器一旦生成， 这些环境变量（http_proxy https_proxy ftp_proxy no_proxy）就会被继承到容器中， 就算把config.json删除， 这个容器依然使用创建时的环境变量，可以手动在容器内重新设置这些环境变量， 这点也挺容易让人头疼的， 一定要注意。")],-1),_=t(`<h2 id="容器使用宿主机的代理的几种方法总结" tabindex="-1"><a class="header-anchor" href="#容器使用宿主机的代理的几种方法总结" aria-hidden="true">#</a> 容器使用宿主机的代理的几种方法总结</h2><p>和 build 时类似，只需要在 生成容器时（run -e http_proxy=...） 或者 容器中 设置环境变量http_proxy和https_proxy变量即可，同样需要注意容易使用的网络类型是bridge还是host，根据类别设置正确的代理 ip 地址</p><h3 id="方法一-直接在容器内使用-推荐" tabindex="-1"><a class="header-anchor" href="#方法一-直接在容器内使用-推荐" aria-hidden="true">#</a> 方法一： 直接在容器内使用（推荐</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token builtin class-name">export</span> <span class="token assign-left variable">ALL_PROXY</span><span class="token operator">=</span><span class="token string">&#39;socks5://172.17.0.1:1080&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>这里ip地址使用的是宿主机的ip</p><h3 id="方法二-与宿主机共享网络时直接在容器内使用" tabindex="-1"><a class="header-anchor" href="#方法二-与宿主机共享网络时直接在容器内使用" aria-hidden="true">#</a> 方法二： 与宿主机共享网络时直接在容器内使用</h3><p>创建容器时使用--network=host参数</p><p>然后在docker内设置代理，比如全局代理</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token builtin class-name">export</span> <span class="token assign-left variable">ALL_PROXY</span><span class="token operator">=</span><span class="token string">&#39;socks5://127.0.0.1:1080&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>这样就可以使用宿主机的代理了</p><p>但是要注意， 如果是用--network=host，这样的话使用 -p 参数映射端口就没用了， 即所有端口都是开放和宿主机共享的</p><h3 id="方法三-映射代理端口后直接在容器内使用" tabindex="-1"><a class="header-anchor" href="#方法三-映射代理端口后直接在容器内使用" aria-hidden="true">#</a> 方法三： 映射代理端口后直接在容器内使用</h3><p>docker run时带参数-p映射代理的端口到容器， 在容器里面使用即可，比如：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">docker</span> run  <span class="token parameter variable">-p</span> <span class="token number">1080</span>:1080 <span class="token punctuation">..</span><span class="token punctuation">..</span>.
<span class="token builtin class-name">export</span> <span class="token assign-left variable">ALL_PROXY</span><span class="token operator">=</span><span class="token string">&#39;socks5://127.0.0.1:1080&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="方法四-docker配置全局代理-以在生成容器时自动设置代理变量" tabindex="-1"><a class="header-anchor" href="#方法四-docker配置全局代理-以在生成容器时自动设置代理变量" aria-hidden="true">#</a> 方法四： docker配置全局代理，以在生成容器时自动设置代理变量</h4><p>设置 docker 全局代理，比如设置了<code>http://172.17.0.1:8123</code> 容器内全都会走这个代理，除了配置文件中的白名单里面的地址以外</p><p>注意： 全局代理和 --network=host 参数只能用一个，不然就容易混乱</p><p>版权声明：本文为 neucrack 的原创文章，遵循 CC 4.0 BY-SA 版权协议</p>`,18),f={href:"https://neucrack.com/p/286",target:"_blank",rel:"noopener noreferrer"};function y(q,P){const n=d("ExternalLinkIcon");return o(),i("div",null,[c,e("p",null,[s("设置方法参考官方文档： "),e("a",p,[s("https://docs.docker.com/network/proxy/"),a(n)])]),u,e("ul",null,[e("li",null,[e("p",null,[s("仅支持 "),h,s(),v,s(),b,s(" 协议，不支持 socks5 协议（2022.3.24，未来不一定，官方文档为准），可以使用polipo创建一个http代理服务，参考"),e("a",m,[s("https://neucrack.com/p/275"),a(n)])])]),k,g,x]),_,e("p",null,[e("a",f,[s("原文链接："),a(n)])])])}const E=r(l,[["render",y],["__file","Proxy.html.vue"]]);export{E as default};
